let measurement = "sensors";
let uid = global.get('uid');
let currentTime = new Date();

function addsensordata(device, value){
    let record = {
        "measurement": measurement,
        "timestamp": currentTime.toISOString(),
        "tags":{
            "UID": uid,
            "device": device,
            "model": value.model,
        },
        "fields": {
            "stationtype": parseFloat(value.stationtype),
            "dateutc": parseFloat(value.dateutc),
            "tempinf": parseFloat(value.tempinf),
            "humidityin": parseFloat(value.humidityin),
            "baromrelin": parseFloat(value.baromrelin),
            "baromabsin": parseFloat(value.baromabsin),
            "tempf": parseFloat(value.tempf),
            "humidity": parseFloat(value.humidity),
            "winddir": parseFloat(value.winddir),
            "winddir_avg10m": parseFloat(value.winddir_avg10m),
            "windspeedmph": parseFloat(value.windspeedmph),
            "maxdailygust": parseFloat(value.maxdailygust),
            "rainratein": parseFloat(value.rainratein),
            "eventrainin": parseFloat(value.eventrainin),
            "hourlyrainin": parseFloat(value.hourlyrainin),
            "dailyrainin": parseFloat(value.dailyrainin),
            "weeklyrainin": parseFloat(value.weeklyrainin),
            "monthlyrainin": parseFloat(value.monthlyrainin),
            "yearlyrainin": parseFloat(value.yearlyrainin),
            "solarradiation": parseFloat(value.solarradiation),
            "uv": parseFloat(value.uv),
        }
    };
    return record;
}

